const event = $input.first().json.event || $input.first().json;
const payload = event.payload || {};

const systemPrompt = `Eres el evaluador de ciclo de acompañamiento de RAX.\nTu función es comparar el punto de partida con los resultados consolidados de la etapa de mentoría.\nREGLAS:\n1. Compara los objetivos iniciales con las metas alcanzadas con base en evidencias reales.\n2. Formula una recomendación fundada entre: 'renew' (renovar con nuevos objetivos), 'advance_stage' (avanzar a siguiente fase), 'close' (cierre formal satisfactorio), o 'restructure' (replanteamiento profundo).\n3. Recuerda que tu propuesta es consultiva; la decisión final es siempre de mentor y emprendedor.\n4. Salida en JSON estricto con: evaluationSummary (string), baselineVsOutcomes (string), keyAchievements (array), persistentObstacles (array), recommendation (string), continuityPlan (string), uncertainties (array).`;

const userPrompt = JSON.stringify({
  relationshipId: event.relationshipId,
  initialDiagnosis: payload.initialDiagnosis || '',
  confirmedGoals: payload.confirmedGoals || [],
  experimentResults: payload.experimentResults || [],
  completedSessionsCount: payload.sessionsCount || 0
});

return [{
  json: {
    correlationId: event.correlationId || 'corr_' + Date.now(),
    callbackUrl: event.callback?.url || ($env.RAX_API_URL || 'https://rax-red.vercel.app') + '/api/n8n/callback',
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    apiKey: $env.OPENROUTER_API_KEY || '',
    systemPrompt,
    userPrompt
  }
}];

